function liftSession(){clearSessionClock();clockRemaining=60;clockKind='rest';document.body.classList.add('lesson-mode');const e=[...workouts[day][exerciseIndex]],plan=data.liftProgress[player+'|'+e[0]]||{};if(plan.target)e[1]=plan.target;const r=cardRecord(),a=liftArt[e[0]],slots=cardSlots(exerciseIndex),finished=r.completed.includes(exerciseIndex),next=slots.find(s=>!r.setChecks[s.key]),count=finished?slots.length:slots.filter(s=>r.setChecks[s.key]).length;hub.innerHTML=`<div class="deck-top"><button data-hub="Today">← Exit</button><span>${workoutNames[day]} <b>${r.completed.length}/5 complete</b></span></div><div class="deck-dots" aria-label="Exercise navigation">${workouts[day].map((w,i)=>`<button data-card-index="${i}" aria-label="Exercise ${i+1}: ${escapeHTML(w[0])}${r.completed.includes(i)?', complete':''}" ${i===exerciseIndex?'aria-current="step"':''} class="${r.completed.includes(i)?'checked':''}">${r.completed.includes(i)?'✓':i+1}</button>`).join('')}</div><article class="athlete-card" tabindex="0" aria-label="${escapeHTML(e[0])} exercise card"><div class="card-ribbon"><span>GALAXY / STRENGTH CLUB</span><b>0${exerciseIndex+1}</b></div><div class="card-art"><span class="card-type">${a.tag}</span>${exerciseGraphic(e[0])}<p>${a.skill}</p></div><div class="card-body"><h1>${e[0]}</h1><div class="card-stats"><div><strong>${r.goalSets}</strong><span>${r.goalSets===1?'SET':'SETS'}</span></div><div><strong>${e[1]}</strong><span>${e[4]==='hold'?'SECONDS':'REPS'}${e[2]?' / SIDE':''}</span></div><div><strong>60<span>s</span></strong><span>REST</span></div></div><p class="card-cue">${a.cue}</p><div class="card-video">${demoLink(strengthDemos[day][exerciseIndex+1][0])}</div><details class="card-details"><summary>Technique & why it matters</summary><p>${e[4]==='hold'?'Hold one light dumbbell. Stay upright; switch hands for the other side.':e[3]}</p><p>${whyExercise[e[0]][0]}</p><p>Use a comfortable load. Stop for pain. Ask an adult to check your form.</p></details><details class="card-details"><summary>Load & next challenge</summary><p>Keep about 2–3 good reps in reserve. If every set feels controlled at the top of your range for two sessions, ask your adult to approve a small increase. Change reps or weight, not both.</p><p>${e[4]==='hold'?'Build a steady hold from 15 toward 25 seconds per side.':'Build from the current target toward 12 controlled reps (dead bug: toward 8 per side).'} Rest 60–90 seconds; take longer if you need it.</p><label>Target ${e[4]==='hold'?'seconds':'reps'}<input id="liftTarget" type="number" min="1" max="30" value="${e[1]}"></label><label>Load per dumbbell (lb; 0 = bodyweight)<input id="liftLoad" type="number" min="0" step="0.5" value="${plan.load||0}"></label><button data-save-lift-plan>Save my target & load</button><p id="liftPlanStatus" role="status"></p><a href="https://www.nsca.com/globalassets/about/position-statements/position_stand_youth_resistance_training---2009.pdf" target="_blank" rel="noopener">Youth strength guidance · NSCA</a></details><div class="card-set-status" role="status">${finished?'✓ All sets complete':`Set ${next.round} of ${r.goalSets}${next.side?' · '+next.side+' side':''}`}<span>${count}/${slots.length} checked</span></div><button class="card-done" data-card-done ${finished?'disabled':''}>${finished?'Exercise complete ✓':next.side?next.side+' side done ✓':'Set done ✓'}</button>${count>0?'<button class="card-undo" data-card-undo>Undo last check</button>':''}</div></article><div class="deck-controls"><button data-card-step="-1" ${exerciseIndex===0?'disabled':''}>← Previous</button><span>Swipe to browse</span><button data-card-step="1" ${exerciseIndex===4?'disabled':''}>Next →</button></div><details class="card-rest"><summary>Rest / hold timer</summary><div class="session-timer"><strong id="sessionSeconds">60</strong><span id="sessionTimerLabel"> seconds · rest</span><div class="row"><button data-run-clock="60">Start rest</button>${e[4]==='hold'?'<button data-run-clock="15">Start hold</button>':''}<button data-pause-clock>Pause</button><button data-resume-clock>Resume</button></div></div></details>`;persist();window.scrollTo(0,0)}
function ballSession(){document.body.classList.add('lesson-mode');hub.innerHTML=`<button data-hub="Today">← Sessions</button><h1>Control, see, connect.</h1><p>Use this instead of extra conditioning. On practice or game days, choose just one short drill if fresh.</p>${['touch','scan','pass'].map((id,i)=>{const l=lessonById[id];return `<details class="quiet-collection" ${i===0?'open':''}><summary>${i+1}. ${l.title}</summary><p><strong>Why:</strong> ${l.why}</p><p><strong>Solo:</strong> ${l.solo}</p><p><strong>Brother:</strong> ${l.duo}</p><p>Try five controlled attempts each, pause to discuss, then repeat once if fresh. Quality before speed.</p>${demoLink(l.video[0])}<details><summary>Add a decision</summary><p>${l.pressure}</p></details></details>`}).join('')}<button data-log="Home session" class="primary">Finish & reflect</button>`}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.liftSession){day=d.liftSession;sessionKey=player+'|'+localDate()+'|'+day;const prior=data.trainingSessions[sessionKey];exerciseIndex=prior?workouts[day].findIndex((_,i)=>!prior.completed.includes(i)):0;if(exerciseIndex<0){showHub('Progress');return}hub.innerHTML=`<button data-hub="Today">← Sessions</button><h1>Get ready.</h1><p>Warm up for 5–10 minutes with easy movement, then rehearse each exercise without weight. Use a stable surface and clear space.</p><p>New to lifting? Have a qualified adult teach and check your form. Soccer experience does not replace lifting instruction.</p><p>Skip this session if sore, unwell or a match is close. Stop for pain.</p><h2>${workoutNames[day]}</h2><p>Choose your training dose. Build uses two working sets per exercise after your technique has been checked. Keep strength days separate and fit them around team training.</p><button data-strength-plan="1">Learn the movements · 1 set</button> <button class="primary" data-strength-plan="2">Build strength · 2 sets</button>`;document.body.classList.add('lesson-mode')}
 if(d.strengthPlan){data.sets[player]=Number(d.strengthPlan);const r=cardRecord();if(!r.completed.length&&!Object.keys(r.setChecks).length)r.goalSets=Number(d.strengthPlan);persist();liftSession()}if(d.liftReady!==undefined)liftSession();if(d.saveLiftPlan!==undefined){const target=Number($('liftTarget').value),load=Number($('liftLoad').value),e=workouts[day][exerciseIndex],limit=e[4]==='hold'?30:15;if(!Number.isFinite(target)||target<1||target>limit||!Number.isFinite(load)||load<0){$('liftPlanStatus').textContent='Check your target and load.';return}data.liftProgress[player+'|'+e[0]]={target,load};persist();liftSession()}if(d.liftBack!==undefined&&exerciseIndex>0){exerciseIndex--;liftSession()}if(d.cardIndex!==undefined){exerciseIndex=Number(d.cardIndex);liftSession()}if(d.cardStep)moveCard(Number(d.cardStep));if(d.cardDone!==undefined){const r=cardRecord(),slots=cardSlots(exerciseIndex),next=slots.find(s=>!r.setChecks[s.key]);if(!r.completed.includes(exerciseIndex)&&next){r.setChecks[next.key]=true;r.prescriptions=r.prescriptions||{};const exercise=workouts[day][exerciseIndex];r.prescriptions[exerciseIndex]={...data.liftProgress[player+'|'+exercise[0]],sets:r.goalSets,target:(data.liftProgress[player+'|'+exercise[0]]||{}).target||exercise[1]};if(slots.every(s=>r.setChecks[s.key]))r.completed.push(exerciseIndex);persist();if(r.completed.length===5){r.completedAt=new Date().toISOString();persist();cardComplete()}else liftSession()}}if(d.cardUndo!==undefined){const r=cardRecord(),slots=cardSlots(exerciseIndex);if(r.completed.includes(exerciseIndex)&&!slots.some(s=>r.setChecks[s.key]))slots.forEach(s=>r.setChecks[s.key]=true);const last=slots.filter(s=>r.setChecks[s.key]).pop();if(last){delete r.setChecks[last.key];r.completed=r.completed.filter(i=>i!==exerciseIndex);delete r.completedAt;persist();liftSession()}}
 if(d.runClock||d.resumeClock!==undefined){clearSessionClock();if(d.runClock){clockRemaining=Number(d.runClock);clockKind=clockRemaining===15?'hold':'rest'}clockDeadline=Date.now()+clockRemaining*1000;const update=()=>{clockRemaining=Math.max(0,Math.ceil((clockDeadline-Date.now())/1000));$('sessionSeconds').textContent=clockRemaining;$('sessionTimerLabel').textContent=clockRemaining?' seconds · '+clockKind:' · complete';if(!clockRemaining)clearSessionClock()};update();if(clockRemaining)sessionClock=setInterval(update,250)}if(d.pauseClock!==undefined){if(sessionClock)clockRemaining=Math.max(0,Math.ceil((clockDeadline-Date.now())/1000));clearSessionClock()}if(d.ballSession!==undefined)ballSession();if(d.log)clearSessionClock();});
showHub('Today');

let cardTouch=null;document.addEventListener('touchstart',e=>{if(e.target.closest('.athlete-card')&&!e.target.closest('button,a,summary'))cardTouch={x:e.touches[0].clientX,y:e.touches[0].clientY};else cardTouch=null},{passive:true});document.addEventListener('touchend',e=>{if(!cardTouch)return;const dx=e.changedTouches[0].clientX-cardTouch.x,dy=e.changedTouches[0].clientY-cardTouch.y;cardTouch=null;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.5)moveCard(dx<0?1:-1)},{passive:true});document.addEventListener('keydown',e=>{if(e.target.closest('.athlete-card')&&!e.target.closest('button,a,summary')){if(e.key==='ArrowRight')moveCard(1);if(e.key==='ArrowLeft')moveCard(-1)}});
